import { useEffect, useState } from "react";
import { createFileRoute, useNavigate } from "@tanstack/react-router";
import { z } from "zod";

import { CasesTable } from "#/components/CasesTable";
import { Button } from "#/components/ui/button";
import { Card, CardContent } from "#/components/ui/card";
import { Input } from "#/components/ui/input";
import {
	Select,
	SelectContent,
	SelectItem,
	SelectTrigger,
	SelectValue,
} from "#/components/ui/select";
import {
	CASES_OVERVIEW_LOAD_LIMIT,
	countCases,
	listCases,
	normalizeCasesOverviewFilters,
} from "#/services/cases";

const CASE_STATUS_ALL = "all" as const;

const CASE_STATUS_OPTIONS = [
	{ value: CASE_STATUS_ALL, label: "All statuses" },
	{ value: "open", label: "Open" },
	{ value: "in_progress", label: "In progress" },
	{ value: "investigating", label: "Investigating" },
	{ value: "blocked", label: "Blocked" },
	{ value: "on_hold", label: "On hold" },
	{ value: "resolved", label: "Resolved" },
] as const;

const casesPageSearchSchema = z.object({
	q: z.string().optional().default(""),
	status: z.string().optional(),
	propertyId: z.string().optional(),
	houseId: z.string().optional(),
	apartmentId: z.string().optional(),
});

function buildCasesSearchPatch(input: {
	q: string;
	status: string;
	propertyId: string;
	houseId: string;
	apartmentId: string;
}): z.infer<typeof casesPageSearchSchema> {
	return {
		apartmentId: input.apartmentId.trim() || undefined,
		houseId: input.houseId.trim() || undefined,
		propertyId: input.propertyId.trim() || undefined,
		q: input.q.trim() || "",
		status:
			input.status === CASE_STATUS_ALL || !input.status.trim()
				? undefined
				: input.status.trim(),
	};
}

export const Route = createFileRoute("/cases")({
	validateSearch: (search) => casesPageSearchSchema.parse(search),
	/** Without this, the loader does not re-run when URL search params change. */
	loaderDeps: ({ search }) => ({
		apartmentId: search.apartmentId ?? "",
		houseId: search.houseId ?? "",
		propertyId: search.propertyId ?? "",
		q: search.q ?? "",
		status: search.status ?? "",
	}),
	loader: async ({ deps }) => {
		const filters = normalizeCasesOverviewFilters({
			apartmentId: deps.apartmentId || undefined,
			houseId: deps.houseId || undefined,
			propertyId: deps.propertyId || undefined,
			q: deps.q || undefined,
			status: deps.status || undefined,
		});
		const total = await countCases(undefined, filters);
		const limit = Math.min(CASES_OVERVIEW_LOAD_LIMIT, Math.max(total, 1));
		const cases = await listCases(undefined, { ...filters, limit });
		return { cases, total };
	},
	component: CasesPage,
});

function CasesPage() {
	const search = Route.useSearch();
	const navigate = useNavigate({ from: Route.fullPath });
	const { cases, total } = Route.useLoaderData();

	const [q, setQ] = useState(search.q);
	const [status, setStatus] = useState(
		search.status && search.status.trim() !== ""
			? search.status
			: CASE_STATUS_ALL,
	);
	const [propertyId, setPropertyId] = useState(search.propertyId ?? "");
	const [houseId, setHouseId] = useState(search.houseId ?? "");
	const [apartmentId, setApartmentId] = useState(search.apartmentId ?? "");

	useEffect(() => {
		setQ(search.q);
		setStatus(
			search.status && search.status.trim() !== ""
				? search.status
				: CASE_STATUS_ALL,
		);
		setPropertyId(search.propertyId ?? "");
		setHouseId(search.houseId ?? "");
		setApartmentId(search.apartmentId ?? "");
	}, [
		search.apartmentId,
		search.houseId,
		search.propertyId,
		search.q,
		search.status,
	]);

	const hasActiveFilters = Boolean(
		search.q.trim() ||
			(search.status && search.status.trim()) ||
			(search.propertyId && search.propertyId.trim()) ||
			(search.houseId && search.houseId.trim()) ||
			(search.apartmentId && search.apartmentId.trim()),
	);

	const headline =
		cases.length < total
			? `${cases.length.toLocaleString()} cases shown (${total.toLocaleString()} matching)`
			: `${cases.length.toLocaleString()} cases loaded`;

	return (
		<main className="px-4 py-6 md:px-6">
			<section className="mb-5 flex flex-col gap-4 sm:flex-row sm:items-start sm:justify-between">
				<div>
					<p className="mb-2 text-sm text-muted-foreground">Cases</p>
					<h1 className="text-2xl font-semibold">{headline}</h1>
					{cases.length < total ? (
						<p className="mt-2 text-sm text-muted-foreground">
							Showing the {cases.length.toLocaleString()} most recently updated
							rows in this view. There are {total.toLocaleString()} matches in
							total.
						</p>
					) : null}
					{hasActiveFilters ? (
						<p className="mt-2 text-sm text-muted-foreground">
							Filters narrow the list. Clear them to see all cases.
						</p>
					) : null}
				</div>
			</section>

			<Card className="mb-6 py-0">
				<CardContent className="py-6">
					<form
						className="grid gap-4 md:grid-cols-2 xl:grid-cols-6"
						onSubmit={async (event) => {
							event.preventDefault();
							await navigate({
								search: buildCasesSearchPatch({
									apartmentId,
									houseId,
									propertyId,
									q,
									status,
								}),
							});
						}}
					>
						<div className="xl:col-span-2">
							<label htmlFor="cases-q" className="mb-2 block text-sm font-medium">
								Search text
							</label>
							<Input
								id="cases-q"
								value={q}
								onChange={(event) => setQ(event.target.value)}
								placeholder="Title, summary, case key, id…"
							/>
						</div>
						<div className="min-w-0">
							<label htmlFor="cases-status" className="mb-2 block text-sm font-medium">
								Status
							</label>
							<Select
								value={status}
								onValueChange={(value) => setStatus(value)}
							>
								<SelectTrigger id="cases-status" className="w-full min-w-0">
									<SelectValue placeholder="All statuses" />
								</SelectTrigger>
								<SelectContent position="popper" sideOffset={4}>
									{CASE_STATUS_OPTIONS.map((opt) => (
										<SelectItem key={opt.value} value={opt.value}>
											{opt.label}
										</SelectItem>
									))}
								</SelectContent>
							</Select>
						</div>
						<div>
							<label
								htmlFor="cases-property-id"
								className="mb-2 block text-sm font-medium"
							>
								Property ID
							</label>
							<Input
								id="cases-property-id"
								value={propertyId}
								onChange={(event) => setPropertyId(event.target.value)}
								placeholder="LIE-001"
							/>
						</div>
						<div>
							<label htmlFor="cases-house-id" className="mb-2 block text-sm font-medium">
								House ID
							</label>
							<Input
								id="cases-house-id"
								value={houseId}
								onChange={(event) => setHouseId(event.target.value)}
								placeholder="LIE-001-H1"
							/>
						</div>
						<div>
							<label
								htmlFor="cases-apartment-id"
								className="mb-2 block text-sm font-medium"
							>
								Apartment ID
							</label>
							<Input
								id="cases-apartment-id"
								value={apartmentId}
								onChange={(event) => setApartmentId(event.target.value)}
								placeholder="LIE-001-H1-A1"
							/>
						</div>
						<div className="flex flex-wrap items-end gap-3 md:col-span-2 xl:col-span-6">
							<Button type="submit">Apply filters</Button>
							<Button
								type="button"
								variant="outline"
								onClick={async () => {
									setQ("");
									setStatus(CASE_STATUS_ALL);
									setPropertyId("");
									setHouseId("");
									setApartmentId("");
									await navigate({
										search: {
											apartmentId: undefined,
											houseId: undefined,
											propertyId: undefined,
											q: "",
											status: undefined,
										},
									});
								}}
							>
								Clear
							</Button>
						</div>
					</form>
				</CardContent>
			</Card>

			<CasesTable cases={cases} />
		</main>
	);
}

